sys_script.script:
(function executeRule(current, previous) {

    var requiredDocs = {
        motor: [
            'claim_form',
            'police_report',
            'repair_invoice',
            'id_proof'
        ],
        health: [
            'claim_form',
            'medical_report',
            'id_proof'
        ],
        property: [
            'claim_form',
            'property_photos',
            'id_proof'
        ],
        travel: [
            'claim_form',
            'incident_report',
            'travel_itinerary',
            'id_proof'
        ]
    };

    var claimType = current.getValue('claim_type');
    var docs = requiredDocs[claimType];

    if (!docs) {
        return;
    }

    for (var i = 0; i < docs.length; i++) {
        var doc = new GlideRecord(
            'x_snc_insurance_0_document'
        );

        doc.initialize();
        doc.setValue('claim_id', current.getUniqueValue());
        doc.setValue('document_type', docs[i]);
        doc.setValue('upload_status', 'missing');
        doc.insert();
    }

})(current, previous);
